// NOTE: This file should not be edited
// see https://nextjs.org/docs/app/building-your-application/configuring/typescript for more information.

// Fix Next.js build: generated .next/types reference internal modules that lack declarations
declare module 'next/dist/lib/metadata/types/metadata-interface.js' {
  export type ResolvingMetadata = unknown;
  export type ResolvingViewport = unknown;
}

// Ensure Next.js runtime modules resolve when TypeScript resolution misses them
declare module 'next/link' {
  import type { ComponentType } from 'react';
  const Link: ComponentType<any>;
  export default Link;
}

declare module 'next/navigation' {
  export function useSearchParams(): ReadonlyURLSearchParams;
  export function usePathname(): string;
  export function useRouter(): { push: (url: string) => void; replace: (url: string) => void; back: () => void };
}
interface ReadonlyURLSearchParams {
  get(name: string): string | null;
  getAll(name: string): string[];
  has(name: string): boolean;
  keys(): IterableIterator<string>;
  entries(): IterableIterator<[string, string]>;
  forEach(callback: (value: string, key: string) => void): void;
  toString(): string;
}

export const metadata = { title: 'KBM Connect Wall', description: 'Event live wall' };

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <head>
        <meta name="viewport" content="width=device-width, initial-scale=1" />
      </head>
      <body
        style={{
          margin: 0,
          fontFamily: 'system-ui, -apple-system, Segoe UI, sans-serif',
          background: 'linear-gradient(180deg, #1a2332 0%, #151d28 55%, #121922 100%)',
          color: '#f8f9fa',
          minHeight: '100vh',
        }}
      >
        {children}
      </body>
    </html>
  );
}

'use client';

import { useEffect, useState } from 'react';
import Link from 'next/link';
import { supabase } from '../lib/supabase';

type Event = { id: string; name: string };

export default function WallHome() {
  const [events, setEvents] = useState<Event[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!supabase) {
      setLoading(false);
      return;
    }
    supabase
      .from('events')
      .select('id, name')
      .eq('is_active', true)
      .order('start_date', { ascending: false })
      .then(({ data }: any) => {
        setEvents(data ?? []);
      })
      .finally(() => setLoading(false));
  }, []);

  const pageShell = {
    padding: 48,
    maxWidth: 800,
    margin: '0 auto',
    minHeight: '100vh',
    color: '#f8f9fa',
  } as const;

  if (loading)
    return (
      <div style={{ ...pageShell, textAlign: 'center', color: 'rgba(248,249,250,0.72)' }}>Loading events…</div>
    );
  if (!events.length)
    return (
      <div style={{ ...pageShell, textAlign: 'center', color: 'rgba(248,249,250,0.72)' }}>
        No active events. Add NEXT_PUBLIC_SUPABASE_* to .env.local.
      </div>
    );

  return (
    <div style={pageShell}>
      <div style={{ width: 36, height: 4, background: '#c9a961', borderRadius: 2, marginBottom: 16 }} aria-hidden />
      <h1 style={{ fontSize: 28, fontWeight: 700, margin: '0 0 8px', letterSpacing: '-0.02em' }}>KBM Connect Wall</h1>
      <p style={{ color: 'rgba(248,249,250,0.72)', marginBottom: 32, fontSize: 15, letterSpacing: '0.02em' }}>
        Select an event for the big screen.
      </p>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {events.map((e) => (
          <li key={e.id} style={{ marginBottom: 12 }}>
            <Link
              href={`/wall?event=${e.id}`}
              style={{
                display: 'block',
                padding: '18px 22px',
                background: '#2d3e50',
                borderRadius: 12,
                color: '#f8f9fa',
                textDecoration: 'none',
                fontSize: 17,
                fontWeight: 600,
                border: '1px solid rgba(201, 169, 97, 0.35)',
                boxShadow: '0 8px 24px rgba(0,0,0,0.25)',
              }}
            >
              {e.name}
            </Link>
          </li>
        ))}
      </ul>
    </div>
  );
}
